import hashlib
import hmac
import os
import time
import sqlite3
import struct
from flask import Flask, request, jsonify, g
from functools import wraps
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))

DB_PATH = '/tmp/acl_service.db'

# PBKDF2 parameters for password hashing
PBKDF2_ITERATIONS = 200000
PBKDF2_ALGO = 'sha256'
PBKDF2_SALT_BYTES = 16


def hash_password(password, salt=None):
    """Return a salted PBKDF2-HMAC-SHA256 hash encoded as 'salt$hexdigest'."""
    if salt is None:
        salt = secrets.token_bytes(PBKDF2_SALT_BYTES)
    dk = hashlib.pbkdf2_hmac(PBKDF2_ALGO, password.encode(), salt, PBKDF2_ITERATIONS)
    return salt.hex() + '$' + dk.hex()


def verify_password(password, stored):
    """Verify a password against a stored 'salt$hexdigest' value."""
    try:
        salt_hex, expected_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
    except (ValueError, AttributeError):
        return False
    dk = hashlib.pbkdf2_hmac(PBKDF2_ALGO, password.encode(), salt, PBKDF2_ITERATIONS)
    return hmac.compare_digest(dk.hex(), expected_hex)


def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

