def compute_effective_level(base_level, department, resource_department):
    """Compute effective access level with department affinity bonus.

    Users in the same department as the resource get a bonus to their
    effective level. Cross-department access requires higher base level.

    The bonus/penalty is applied as a delta to create the effective level.
    Effective level is clamped to non-negative to prevent underflow issues.
    """
    if department == resource_department:
        # Same department: +15 bonus
        delta = 15
    elif department == 'executive':
        # Executive department: no penalty for cross-department
        delta = 0
    else:
        # Cross-department: -20 penalty
        delta = -20

    # Apply delta to get effective level, clamp to 0 minimum
    effective = max(0, base_level + delta)
    return effective

def check_access(user_role_level, user_department, resource):
    """Determine if user can access the resource based on effective level.

    Returns True if the user's effective level meets or exceeds the
    resource's required level.
    """
    required = resource['required_level']

    # Resources with required_level 0 are public
    if required == 0:
        return True

    effective = compute_effective_level(
        user_role_level, user_department, resource['department']
    )

    # Access granted if effective level sufficient
    return effective >= required

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token:
            return jsonify({'error': 'Authentication required'}), 401

        db = get_db()
        session = db.execute(
            'SELECT * FROM sessions WHERE token = ? AND expires_at > ?',
            (token, time.time())
        ).fetchone()

        if not session:
            return jsonify({'error': 'Invalid or expired session'}), 401

        user = db.execute(
            'SELECT * FROM users WHERE id = ?',
            (session['user_id'],)
        ).fetchone()

        if not user:
            return jsonify({'error': 'User not found'}), 401

        g.current_user = user
        return f(*args, **kwargs)
    return decorated

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password']

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?',
        (username,)
    ).fetchone()

    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401

    if not verify_password(password, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = secrets.token_urlsafe(32)
    expires = time.time() + 3600

    db.execute(
        'INSERT INTO sessions (token, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)',
        (token, user['id'], time.time(), expires)
    )
    db.commit()

    return jsonify({'token': token, 'expires_in': 3600})

@app.route('/api/resources/<int:resource_id>', methods=['GET'])
@authenticate
def get_resource(resource_id):
    db = get_db()
    resource = db.execute(
        'SELECT * FROM resources WHERE id = ?',
        (resource_id,)
    ).fetchone()

    if not resource:
        return jsonify({'error': 'Resource not found'}), 404

    user = g.current_user

    if not check_access(user['role_level'], user['department'], resource):
        return jsonify({'error': 'Access denied'}), 403

    return jsonify({
        'id': resource['id'],
        'name': resource['name'],
        'content': resource['content'],
        'department': resource['department']
    })

@app.route('/api/resources', methods=['GET'])
@authenticate
def list_resources():
    db = get_db()
    resources = db.execute('SELECT * FROM resources').fetchall()
    user = g.current_user

    accessible = []
    for resource in resources:
        if check_access(user['role_level'], user['department'], resource):
            accessible.append({
                'id': resource['id'],
                'name': resource['name'],
                'department': resource['department']
            })

    return jsonify({'resources': accessible})

@app.route('/api/profile', methods=['GET'])
@authenticate
def get_profile():
    user = g.current_user
    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'role_level': user['role_level'],
        'department': user['department']
    })

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000)
